//! Differential parity against the real TS engine: the main parity guarantee.
//!
//! `fixtures/differential.json` (generated by `scripts/differential.ts`) holds
//! 169 full matches. For the initial state and after every transition the
//! generator builds one point string:
//!
//! ```text
//! JSON.stringify({ views, steps, legal }) \n JSON.stringify(state) \n battery
//! ```
//!
//! where `battery` is every seat's outcome (`ok:<turnId>;` or
//! `<code>:<legal ids>;`) for a fixed list of candidate moves plus a stale
//! `turnId`. The fixture keeps, per point, the engine `fnv1a` of that string
//! (to locate a mismatch) and, per game, the SHA-256 of every point string in
//! order (the byte-identity guarantee), plus the final `turnId`.
//!
//! This test rebuilds every point string with the Rust engine and asserts both
//! hashes, so every projected view, redacted step list, legal set, persisted
//! state, rejection code and rejection legal set is byte-identical to TS.
//!
//! On a mismatch it prints the seed, the transition index and both point
//! strings (the TS side via `bun run scripts/differential.ts --dump`).

mod common;

use std::collections::HashSet;

use common::*;
use euchre_engine::{
    ApplyError, ApplyOptions, EngineConfigOverrides, GameInit, GamePhase, GameState, GameStatus,
    Move, PublicGameView, RuleCode, Seat, Step, create_game, fnv1a, legal_move_ids, legal_moves,
    mulberry32, project, project_steps, try_advance, try_apply,
};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

const FIXTURE: &str = include_str!("fixtures/differential.json");

/// Games are split into this many `#[test]`s so they replay in parallel.
const SHARDS: usize = 8;

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Fixture {
    games: Vec<GameFixture>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct GameFixture {
    seed: String,
    game_id: String,
    cfg: Option<EngineConfigOverrides>,
    first_dealer: Option<Seat>,
    internal_token: Option<String>,
    picker: String,
    transitions: usize,
    final_turn_id: String,
    sha256: String,
    points: Vec<u32>,
}

/// The compared view payload; field order is the TS object literal's key order.
#[derive(Serialize)]
struct Payload {
    views: Vec<PublicGameView>,
    steps: Vec<Vec<Step>>,
    legal: Vec<Vec<String>>,
}

/// `passHeavyPicker` with a configurable stream and pass rate.
fn pass_picker(stream: &str, rate: f64) -> Picker {
    let mut rnd = mulberry32(fnv1a(stream));
    Box::new(move |state, _seat, legal| {
        let bidding = matches!(
            state.hand.phase,
            GamePhase::BidRound1 | GamePhase::BidRound2
        );
        if bidding
            && rnd() < rate
            && let Some(pass) = legal.iter().find(|m| m.id == "pass")
        {
            return pass.clone();
        }
        legal[pick_index(rnd(), legal.len())].clone()
    })
}

fn picker(kind: &str, seed: &str) -> Picker {
    match kind {
        "random" => random_picker(seed),
        "passHeavy" => pass_heavy_picker(seed),
        "passMost" => pass_picker(&format!("{seed}#pass-most"), 0.98),
        "alone" => alone_picker(seed),
        "randomAlt" => random_picker(&format!("{seed}#alt")),
        other => panic!("unknown picker {other}"),
    }
}

/// The generator's fixed candidate moves for `seat`, in the same order.
fn candidates(state: &GameState, seat: Seat) -> Vec<Move> {
    let held = &state.hand.hands[seat.index()];
    let mut out = vec![
        Move::Pass,
        Move::OrderUp { alone: false },
        Move::OrderUp { alone: true },
    ];
    for suit in ALL_SUITS {
        out.push(Move::Call { suit, alone: false });
    }
    out.push(Move::Call {
        suit: s('H'),
        alone: true,
    });
    out.push(Move::Cut { cut: true });
    out.push(Move::Cut { cut: false });
    out.push(Move::Discard {
        card: held.first().copied().unwrap_or_else(|| c("9S")),
    });
    out.push(Move::Discard { card: c("AS") });
    out.extend(held.iter().map(|&card| Move::Play { card }));
    out.push(Move::Play { card: c("AS") });
    out.push(Move::Play { card: c("9H") });
    out
}

fn outcome(state: &GameState, seat: Seat, mv: Move, opts: Option<&ApplyOptions>) -> String {
    match try_apply(state, seat, mv, opts) {
        Ok(r) => format!("ok:{};", r.state.turn_id),
        Err(ApplyError::Rule(e)) => {
            let ids: Vec<&str> = e.legal.iter().map(|m| m.id.as_str()).collect();
            format!("{}:{};", e.code, ids.join(","))
        }
        Err(ApplyError::Fault(e)) => format!("fault:{e};"),
    }
}

/// Every seat's outcome for every candidate, plus a stale-`turnId` pass.
fn battery(state: &GameState) -> String {
    let stale = ApplyOptions {
        turn_id: Some("stale".to_owned()),
    };
    let mut buf = String::new();
    for seat in SEATS_ALL {
        buf.push_str(&format!(
            "{seat}|stale:{}",
            outcome(state, seat, Move::Pass, Some(&stale))
        ));
        for mv in candidates(state, seat) {
            buf.push_str(&outcome(state, seat, mv, None));
        }
        buf.push('\n');
    }
    buf
}

/// The compared point string, built exactly as the generator builds it.
fn point(state: &GameState, steps: &[Step]) -> String {
    let view = json(&Payload {
        views: SEATS_ALL.iter().map(|&s| project(state, s)).collect(),
        steps: SEATS_ALL.iter().map(|&s| project_steps(steps, s)).collect(),
        legal: SEATS_ALL
            .iter()
            .map(|&s| legal_move_ids(state, s))
            .collect(),
    });
    format!("{view}\n{}\n{}", json(state), battery(state))
}

/// The TS side of a mismatch, best effort (needs `bun` and the TS source).
fn ts_dump(seed: &str, index: usize) -> String {
    let script = concat!(env!("CARGO_MANIFEST_DIR"), "/scripts/differential.ts");
    match std::process::Command::new("bun")
        .args(["run", script, "--dump", seed, &index.to_string()])
        .output()
    {
        Ok(out) if out.status.success() => String::from_utf8_lossy(&out.stdout).into_owned(),
        Ok(out) => format!(
            "(dump failed: {})",
            String::from_utf8_lossy(&out.stderr).trim()
        ),
        Err(e) => format!("(could not run bun: {e}; run `bun run {script} --dump {seed} {index}`)"),
    }
}

fn check_point(g: &GameFixture, index: usize, pt: &str) {
    let got = fnv1a(pt);
    let want = g.points.get(index);
    if want == Some(&got) {
        return;
    }
    panic!(
        "differential mismatch: seed {} transition {index} (point hash {got} vs TS {want:?})\n\
         --- Rust point ---\n{pt}\n--- TS point ---\n{}",
        g.seed,
        ts_dump(&g.seed, index)
    );
}

/// Replays one match, checking every point; returns the number of points.
fn replay(g: &GameFixture) -> usize {
    let mut state = create_game(GameInit {
        game_id: g.game_id.clone(),
        seed: g.seed.clone(),
        cfg: g.cfg,
        internal_token: g.internal_token.clone(),
        first_dealer: g.first_dealer,
    });
    let mut pick = picker(&g.picker, &g.seed);
    let mut sha = Sha256::new();
    let mut visit = |index: usize, state: &GameState, steps: &[Step]| {
        let pt = point(state, steps);
        check_point(g, index, &pt);
        sha.update(pt.as_bytes());
        sha.update(b"\n");
    };
    let mut index = 0;
    visit(index, &state, &[]);
    while state.status == GameStatus::Active {
        assert!(index <= 20000, "{}: budget exhausted", g.seed);
        let res = match state.hand.turn_seat {
            None => try_advance(&state).unwrap_or_else(|e| panic!("{}: {e}", g.seed)),
            Some(seat) => {
                let legal = legal_moves(&state, seat);
                let chosen = pick(&state, seat, &legal);
                try_apply(&state, seat, chosen.mv, None)
                    .unwrap_or_else(|e| panic!("{} #{index}: {e}", g.seed))
            }
        };
        state = res.state;
        index += 1;
        visit(index, &state, &res.steps);
    }
    assert_eq!(index, g.transitions, "{}: transition count", g.seed);
    assert_eq!(state.turn_id, g.final_turn_id, "{}: final turnId", g.seed);
    assert_eq!(
        hex::encode(sha.finalize()),
        g.sha256,
        "{}: SHA-256 over every point string differs from TS although each \
         per-point fnv1a matched",
        g.seed
    );
    index + 1
}

fn fixture() -> Fixture {
    serde_json::from_str(FIXTURE).unwrap_or_else(|e| panic!("differential.json: {e}"))
}

/// Replays the games whose fixture index is `shard` modulo [`SHARDS`].
fn replay_shard(shard: usize) {
    let f = fixture();
    let mut points = 0;
    for g in f.games.iter().skip(shard).step_by(SHARDS) {
        points += replay(g);
    }
    assert!(points > 2_000, "shard {shard}: {points} points");
}

#[test]
fn fixture_covers_the_required_combinations() {
    let f = fixture();
    assert_eq!(f.games.len(), 160 + 5 + 4);

    // The full cross product: cfg x first dealer (drawn or each seat) x picker.
    type Combo = (Option<u8>, Option<bool>, Option<bool>, Option<Seat>, String);
    let combos: HashSet<Combo> = f
        .games
        .iter()
        .map(|g| {
            let cfg = g.cfg.unwrap_or_default();
            (
                cfg.game_to,
                cfg.stick_the_dealer,
                cfg.require_natural_trump,
                g.first_dealer,
                g.picker.clone(),
            )
        })
        .collect();
    let dealers: Vec<Option<Seat>> = std::iter::once(None)
        .chain(SEATS_ALL.iter().copied().map(Some))
        .collect();
    for game_to in [5, 10] {
        for stick in [true, false] {
            for natural in [true, false] {
                for &dealer in &dealers {
                    for kind in ["random", "passHeavy", "alone", "randomAlt"] {
                        assert!(
                            combos.contains(&(
                                Some(game_to),
                                Some(stick),
                                Some(natural),
                                dealer,
                                kind.to_owned()
                            )),
                            "missing gameTo {game_to} stick {stick} natural {natural} \
                             dealer {dealer:?} picker {kind}"
                        );
                    }
                }
            }
        }
    }

    // Config values and init fields outside the cross product.
    let game_tos: HashSet<u8> = f
        .games
        .iter()
        .filter_map(|g| g.cfg.and_then(|c| c.game_to))
        .collect();
    for want in [5, 7, 10, 11] {
        assert!(game_tos.contains(&want), "missing gameTo {want}");
    }
    let limits: HashSet<u8> = f
        .games
        .iter()
        .filter_map(|g| g.cfg.and_then(|c| c.misdeal_limit))
        .collect();
    assert_eq!(limits, HashSet::from([1, 5]));
    assert!(f.games.iter().any(|g| g.internal_token.is_some()));
    assert!(f.games.iter().any(|g| g.cfg.is_none()));

    for g in &f.games {
        assert_eq!(g.points.len(), g.transitions + 1, "{}", g.seed);
        assert_eq!(g.sha256.len(), 64, "{}", g.seed);
    }
    let points: usize = f.games.iter().map(|g| g.points.len()).sum();
    assert!(points > 30_000, "{points}");
}

#[test]
fn the_misdeal_limit_rows_reach_their_cap() {
    // Guards the fixture's intent: the misdealLimit rows must actually throw in
    // often enough for the cap to bind, or they compare nothing new.
    let f = fixture();
    for g in f
        .games
        .iter()
        .filter(|g| g.seed.starts_with("diff-misdeal-"))
    {
        let limit = g.cfg.and_then(|c| c.misdeal_limit).unwrap_or(3);
        let mut state = create_game(GameInit {
            game_id: g.game_id.clone(),
            seed: g.seed.clone(),
            cfg: g.cfg,
            internal_token: None,
            first_dealer: g.first_dealer,
        });
        let mut pick = picker(&g.picker, &g.seed);
        let mut max_streak = 0;
        while state.status == GameStatus::Active {
            max_streak = max_streak.max(state.misdeal_streak);
            state = match state.hand.turn_seat {
                None => try_advance(&state).unwrap_or_else(|e| panic!("{e}")).state,
                Some(seat) => {
                    let legal = legal_moves(&state, seat);
                    let chosen = pick(&state, seat, &legal);
                    try_apply(&state, seat, chosen.mv, None)
                        .unwrap_or_else(|e| panic!("{e}"))
                        .state
                }
            };
        }
        assert_eq!(max_streak, limit, "{}", g.seed);
    }
}

/// The rule codes a battery string contains.
fn battery_codes(battery: &str) -> HashSet<RuleCode> {
    battery
        .split([';', '\n'])
        .map(|tok| tok.rsplit_once('|').map_or(tok, |(_, t)| t))
        .map(|tok| tok.strip_prefix("stale:").unwrap_or(tok))
        .filter_map(|tok| tok.split_once(':').map(|(code, _)| code))
        .filter_map(|code| code.parse::<RuleCode>().ok())
        .collect()
}

#[test]
fn the_battery_reaches_every_rule_code_and_game_over_rejects_everything() {
    // Guards the fixture's intent: the rejection battery must exercise every
    // `RuleCode` (so each code's legal set is compared with TS), and once a
    // match is over every candidate from every seat is `wrong_phase`.
    let f = fixture();
    let mut seen: HashSet<RuleCode> = HashSet::new();
    for g in &f.games {
        let mut state = create_game(GameInit {
            game_id: g.game_id.clone(),
            seed: g.seed.clone(),
            cfg: g.cfg,
            internal_token: g.internal_token.clone(),
            first_dealer: g.first_dealer,
        });
        let mut pick = picker(&g.picker, &g.seed);
        while state.status == GameStatus::Active {
            if seen.len() < RuleCode::ALL.len() {
                seen.extend(battery_codes(&battery(&state)));
            }
            state = match state.hand.turn_seat {
                None => try_advance(&state).unwrap_or_else(|e| panic!("{e}")).state,
                Some(seat) => {
                    let legal = legal_moves(&state, seat);
                    let chosen = pick(&state, seat, &legal);
                    try_apply(&state, seat, chosen.mv, None)
                        .unwrap_or_else(|e| panic!("{e}"))
                        .state
                }
            };
        }
        let over = battery(&state);
        assert_eq!(
            battery_codes(&over),
            HashSet::from([RuleCode::WrongPhase]),
            "{}",
            g.seed
        );
        assert!(!over.contains("ok:"), "{}", g.seed);
    }
    let missing: Vec<&RuleCode> = RuleCode::ALL.iter().filter(|c| !seen.contains(c)).collect();
    assert!(missing.is_empty(), "battery never produced {missing:?}");
}

macro_rules! shard_tests {
    ($($name:ident => $shard:expr),* $(,)?) => {
        $(
            #[test]
            fn $name() {
                replay_shard($shard);
            }
        )*
    };
}

shard_tests! {
    every_transition_is_byte_identical_to_ts_shard_0 => 0,
    every_transition_is_byte_identical_to_ts_shard_1 => 1,
    every_transition_is_byte_identical_to_ts_shard_2 => 2,
    every_transition_is_byte_identical_to_ts_shard_3 => 3,
    every_transition_is_byte_identical_to_ts_shard_4 => 4,
    every_transition_is_byte_identical_to_ts_shard_5 => 5,
    every_transition_is_byte_identical_to_ts_shard_6 => 6,
    every_transition_is_byte_identical_to_ts_shard_7 => 7,
}

#[test]
fn shards_cover_every_game_once() {
    let n = fixture().games.len();
    let mut seen = vec![0; n];
    for shard in 0..SHARDS {
        for i in (shard..n).step_by(SHARDS) {
            seen[i] += 1;
        }
    }
    assert!(seen.iter().all(|&k| k == 1));
}
